# Each task is an independent operator job, with its own deliverable and success test.
TASKS=[]
def task(slug,title,group,goal,steps,rows,metric,mistake,source):
 TASKS.append(dict(slug=slug,title=title,group=group,goal=goal,steps=steps,rows=rows,metric=metric,mistake=mistake,source=source))
